/** Grid position of the authored `@`. */
export function startPos(map: GameMap): { x: number; y: number } {
  for (let y = 0; y < map.tiles.length; y++) {
    const x = map.tiles[y].indexOf('@');
    if (x !== -1) return { x, y };
  }
  throw new Error('map has no start tile');
}
